CREATE TABLE IF NOT EXISTS nfc_registration_sessions(session_id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES identity_members(member_id),hardware_id TEXT NOT NULL,status TEXT NOT NULL,card_uid TEXT,credential_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,completed_at TEXT); CREATE INDEX IF NOT EXISTS ix_nfc_registration_device_status ON nfc_registration_sessions(hardware_id,status,created_at); CREATE INDEX IF NOT EXISTS ix_nfc_registration_member ON nfc_registration_sessions(member_id,created_at);